CREATE OR REPLACE FUNCTION mission_generic_owner.c7_run_budget_v1(p_session uuid, p_next boolean, p_current_work uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare named47 boolean:=false;a mission_generic_owner.dispatch_admissions;g mission_generic_owner.provider_policy;
 pol mission_narrative_internal.runtime_policy;spent numeric;calls bigint;bound numeric;capcost numeric;capcalls integer;ok boolean;scene_policy jsonb;
 rr mission_factory_owner.editor_release_readiness; campaign jsonb; clean_policy jsonb;
 asof timestamptz; provider_deadline timestamptz; history_ids uuid[];
 hist_c bigint;hist_g bigint;hist_h bigint;hist_usd numeric;
 actual_c bigint;actual_g bigint;actual_h bigint;actual_usd numeric;
 hold_c bigint;hold_g bigint;new_pair integer;campaign_ok boolean;own_work mission_generic_owner.work_items;campaign_scope boolean;root_text text;stop_causes jsonb:='[]'::jsonb;
 second31 boolean;third36 boolean;fourth38 boolean;fifth40 boolean;sixth43 boolean;seventh46 boolean;cap_pairs31 integer;cap_c31 integer;cap_g31 integer;cap_h31 integer;cap_usd31 numeric;hist31 jsonb;res31 jsonb;history31 jsonb;
begin
 perform mission_ai_board_owner.service_only();
 -- C9: freeze policy DML through proof, Native reserve and authorization.
 LOCK TABLE mission_narrative_internal.runtime_policy IN SHARE MODE;
 -- Same admission/policy locks at claim and all subsequent boundaries.
 select * into strict pol from mission_narrative_internal.runtime_policy where singleton;
 select * into strict a from mission_generic_owner.dispatch_admissions where master_session_id=p_session for update;
 select * into strict g from mission_generic_owner.provider_policy where singleton for share;
 campaign_scope:=NOT EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 ma WHERE ma.master_session_id=p_session) AND (EXISTS(WITH historical_proofs AS MATERIALIZED (
 SELECT wc0.*,mission_generic_owner.c1266_historical_work_v1(wc0.work_id) AS historical_proof
 FROM mission_public_owner.work_contracts_v1 wc0
 WHERE wc0.master_session_id=p_session AND wc0.scope='staff_mission'
 AND wc0.contract->>'schema_version'='mission-narrative-admission/3'
