 campaign:=root_text::jsonb#>'{config,c1266_staff_campaign}';clean_policy:=root_text::jsonb#>'{config,c1266_clean_staff}';
 named47:=coalesce((campaign='{"maxGen":17,"maxUSD":"0.4216","maxHTTP":34,"grant_id":"b925043a-c1b3-434b-8fb4-f335903b2af0","maxCount":17,"residual":{"gen":17,"usd":"0.4395760","http":34,"count":17},"max_pairs":17,"expires_at":"2026-10-20T15:12:18.393948+00:00","not_before":"2026-10-20T14:12:18.393948+00:00","campaign_id":"b2fc5e28-072b-41f2-8dd8-cb5a35a13092","location_id":"0b85f354-9cdb-47e1-baf9-3d266bb7e06b","work_seconds":360,"schema_version":"c1266-staff-campaign/2","cleanup_seconds":360,"history_baseline":{"gen":33,"usd":"0.5524240","http":69,"count":36},"history_scope_ids":["0b1fa6b5-d9c4-4ea3-9ec8-76b1b21e0a0a","21fb8bf3-1df9-4bbf-b2d6-cf7b003b8f30","a853d33f-eecf-484b-b85c-5dc12c25d080","d25d886e-e4f8-4cfe-b8f2-729e96f355d7","c21baa1a-cdac-4401-9131-493eef208a21","780bc131-229e-4142-b1f9-4c6a39b6d070","ef12969b-0958-473c-9016-53052af9d579","2067ace7-c975-4e6c-a621-f82ac23ed18d","6c8d9647-b0de-4c2c-a7e0-6c4a6239ee86","41ec7f9e-9c2c-4476-be14-3ba57a573bc5","8b814fa7-fcdb-4035-9ddb-5bea247aeb36"],"time_policy":{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}}'::jsonb AND clean_policy='{"grant_id":"b925043a-c1b3-434b-8fb4-f335903b2af0","expires_at":"2026-10-20T15:12:18.393948+00:00","not_before":"2026-10-20T14:12:18.393948+00:00","location_id":"0b85f354-9cdb-47e1-baf9-3d266bb7e06b","source_sha256":"eca0639f48346ed0c1fac786c136f557920b61310c38d85f22a5e6a7837231bd","schema_version":"c1266-clean-staff-admission-policy/2","source_mission_id":"5878822d-dc03-4ac2-ad0b-1547f0ab3fc0","source_plan_version_id":"24b1e44a-5597-4fb0-95bd-fb13647764b2","c7_budget_qualification":{"model":"gpt-6-luna","store":false,"http_limit":28,"schema_version":"c1266-clean-staff-budget-qualification/1","generation_limit":14,"reasoning_effort":"high","input_usd_million":0.1,"input_tokens_limit":24000,"output_usd_million":0.5,"output_tokens_limit":20000,"count_upper_cost_usd":"0.0124","scene_cost_budget_usd":"0.3136","generation_upper_cost_usd":"0.0124","count_qu