   'scene_policy_sha256',public.combat_v2_sha256(scene_policy),'backing_origin','finite_columns_not_effective_staff_ceilings');
 END IF;

 return jsonb_build_object('enforced',true,'allowed',ok,'manual_count_limit',mission_generic_owner.manual_staff_count_limit_v1(p_session),'remaining_calls',CASE WHEN mission_generic_owner.manual_staff_count_limit_v1(p_session)='none' THEN NULL ELSE greatest(0,capcalls-calls) END,
 'spent_usd',spent,'upper_bound_next_usd',bound,'call_limit',CASE WHEN mission_generic_owner.manual_staff_count_limit_v1(p_session)='none' THEN NULL ELSE capcalls END,'cost_limit_usd',capcost,
 'qualification_sha256',a.c7_budget_qualification_sha256,'count_upper_cost_usd',a.c8_count_upper_cost_usd,'count_qualification_sha256',a.c8_count_qualification_sha256,'http_slots_per_generation',2);
end $function$

mission_generic_owner__provider_native_a.source:
CREATE OR REPLACE FUNCTION mission_generic_owner.provider_native_assert(p_receipt uuid, p_stage text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r mission_narrative_internal.dispatch_receipts;w mission_generic_owner.work_items;
 k mission_generic_owner.provider_permits;g mission_generic_owner.provider_policy;
 a mission_generic_owner.dispatch_admissions;pol mission_narrative_internal.runtime_policy;
 run_spent numeric;day_spent numeric;all_spent numeric;run_calls bigint;day_calls bigint;all_calls bigint;
 ub numeric;extra numeric;extra_call integer;env jsonb;narrative_contract jsonb;
 ordinary_qualified boolean:=false;staff_root_budget boolean:=false;staff_mode boolean;staff_spent numeric;staff_calls bigint;
 shared_on boolean;shared_paused boolean;shared_bound numeric;shared_price staff_ai_quota_private.prices%rowtype;shared_ticket jsonb;
begin
 if p_stage not in('reserve','authorize','consume') then raise exception 'MGPG_STAGE';end if;
 select * into strict r from mission_narrative_internal.dispatch_receipts where id=p_receipt;
 select * into strict w from mission_generic_owner.work_items where id=r.authority_receipt_id and dispatch_receipt_id=r.id;


 select * into strict k from mission_generic_owner.provider_permits where work_id=w.id and receipt_id=r.id;
 if k.transaction_id<>txid_current() or k.backend_pid<>pg_backend_pid()
 or k.stage<>(case p_stage when 'consume' then 'consume' else 'authorize' end)
 or k.lease_id<>w.lease_id or k.payload_sha256<>w.payload_sha256 or w.lease_expires_at<=clock_timestamp()
 or w.state<>(case p_stage when 'consume' then 'authorized' else 'claimed' end)
 or r.status<>(case p_stage when 'reserve' then 'claimed' when 'authorize' then 'reserved' else 'authorized' end)
 or r.event_kind<>'mission_generic_event' or r.renderer_version<>'mission-generic-runtime/1'
 or r.master_session_id<>w.master_session_id or r.request_key<>w.request_key
 then raise exception 'MGPG_PERMIT_INVALID';end if;
 perform mission_generic_owner.provider_ready(w.id);
 -- C9: only the verified Native same-TX permit may enter admission budget locks.
 if p_stage='reserve' and (mission_generic_owner.c7_run_budget_v1(w.master_session_id,true,w.id)->>'allowed')='false'
 then raise exception 'MGPG_C7_RUN_BUDGET_STOP' using errcode='55000';end if;
 env:=jsonb_build_object('work_id',w.id,'master_session_id',w.master_session_id,'event_id',w.event_id,
 'authority_receipt_id',w.authority_receipt_id,'payload_sha256',w.payload_sha256,'definition_sha256',w.definition_sha256,'revision',w.revision);
 narrative_contract:=mission_public_owner.work_contract_v1(w.id);
 if narrative_contract is not null then env:=env||jsonb_build_object('narrative_admission',narrative_contract);end if;
 if r.envelope<>env or r.envelope_sha256<>public.combat_v2_sha256(env) or r.authority_sha256<>public.combat_v2_sha256(env)
 then raise exception 'MGPG_ENVELOPE_INVALID';end if;
 select * into strict g from mission_generic_owner.provider_policy where singleton;
 select * into strict a from mission_generic_owner.dispatch_admissions where master_session_id=w.master_session_id;
 select * into strict pol from mission_narrative_internal.runtime_policy where singleton;
 staff_mode:=mission_academy_owner.staff_carrier_runtime(w.master_session_id);
 IF EXISTS(SELECT 1 FROM public.master_v2_sessions s726 WHERE s726.id=w.master_session_id AND s726.owner_kind='ai_service' AND s726.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND (EXISTS(SELECT 1 FROM mission_generic_owner.flow_staff_sessions f726 WHERE f726.master_session_id=s726.id AND f726.enabled) OR EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources q726 WHERE q726.session_id=s726.id AND q726.availability_scope='staff' AND q726.execution_context='staff_simulation'))) AND NOT mission_academy_owner.staff_carrier_runtime(w.master_session_id) AND NOT mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id) THEN RAISE EXCEPTION 'C726_FACTORY_STAFF_SCOPE_CLOSED' USING ERRCODE='42501';END IF;
 staff_root_budget:=mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id);staff_mode:=staff_mode OR staff_root_budget;

 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) AND mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true) IS NULL THEN RAISE EXCEPTION 'C1266_NATIVE5_CLOSED' USING ERRCODE='42501';END IF;
 ordinary_qualified:=mission_generic_owner.c758_admission_proof_v1(w.master_session_id);
 IF ordinary_qualified AND p_stage='reserve' THEN PERFORM mission_generic_owner.c758_ordinary_budget_assert_v1(w.master_session_id,w.id);END IF;
 if pol.model<>'gpt-6-luna' or pol.reasoning_effort<>'high' or pol.store
 or pol.max_input_tokens<=0 or pol.max_output_tokens<=0
 or not(pol.input_usd_million>=0 and pol.input_usd_million<'Infinity'::numeric)
 or not(pol.output_usd_million>=0 and pol.output_usd_million<'Infinity'::numeric)
 then raise exception 'MGPG_NATIVE_PRICING_POLICY';end if;
 pol.max_input_tokens:=mission_generic_owner.receipt_input_cap(r.id,pol.max_input_tokens);
 ub:=(pol.max_input_tokens*pol.input_usd_million+pol.max_output_tokens*pol.output_usd_million)/1000000;
 if ub>0.20::numeric then raise exception 'MGPG_CALL_BUDGET_EXHAUSTED';end if;
 -- Native reserve holds runtime_policy FOR UPDATE before this sum. Other phases
 -- only validate an already charged reservation; no second reservation is added.
 select coalesce(sum(cost)filter(where d.master_session_id=w.master_session_id),0),
 coalesce(sum(cost)filter(where d.created_at>=date_trunc('day',clock_timestamp())),0),coalesce(sum(cost),0),
 coalesce(sum(http_calls)filter(where d.master_session_id=w.master_session_id),0),
 coalesce(sum(http_calls)filter(where d.created_at>=date_trunc('day',clock_timestamp())),0),coalesce(sum(http_calls),0)
 into run_spent,day_spent,all_spent,run_calls,day_calls,all_calls
 from (select d.*,mission_factory_owner.qc2_dispatch_cost_v1(d.id,case when d.status in('success','fallback','unknown_billable') or (d.quest_compile_request is not null and d.status='failed') then coalesce(d.charged_cost_usd,d.upper_bound_cost_usd,0)
 else coalesce(d.upper_bound_cost_usd,0) end) cost,
 mission_factory_owner.qc2_dispatch_calls_v1(d.id,exists(select 1 from mission_narrative_internal.dispatch_attempts t where t.receipt_id=d.id)) http_calls
 from mission_narrative_internal.dispatch_receipts d where (d.event_kind='mission_generic_event' and d.renderer_version='mission-generic-runtime/1') or d.quest_compile_request is not null) d;
 extra:=case when p_stage='reserve' then ub else 0 end;extra_call:=case when p_stage='reserve' then 1 else 0 end;
 if mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NULL and (not staff_mode or (a.c7_budget_enforced and p_stage='reserve')) and (run_spent+extra>least(g.run_budget_usd,a.cost_budget_usd)
 or (NOT (mission_generic_owner.manual_staff_count_limit_v1(w.master_session_id)='none') AND run_calls+extra_call>CASE WHEN staff_root_budget OR (ordinary_qualified AND mission_generic_owner.c1266_opening_named_v1(w.master_session_id)) THEN 2*least(g.max_run_calls,a.call_limit) ELSE least(g.max_run_calls,a.call_limit) END))
 then raise exception 'MGPG_BUDGET_EXHAUSTED';end if;
 IF ordinary_qualified AND (day_spent+extra>g.daily_budget_usd OR all_spent+extra>g.global_budget_usd OR (NOT (mission_generic_owner.manual_staff_count_limit_v1(w.master_session_id)='none') AND(day_calls+extra_call>g.max_daily_calls OR all_calls+extra_call>g.max_global_calls))) THEN RAISE EXCEPTION 'MGPG_BUDGET_EXHAUSTED';END IF;
 if staff_mode OR ordinary_qualified then
   select enabled,admissions_paused into strict shared_on,shared_paused
     from staff_ai_quota_private.runtime where singleton for update;
   if shared_paused then raise exception 'STAFF_QUOTA_ADMISSIONS_PAUSED' using errcode='55000';end if;
   IF ordinary_qualified AND NOT shared_on THEN RAISE EXCEPTION 'C758_ORDINARY_SHARED_QUOTA_CLOSED' USING ERRCODE='55000';END IF;
   if shared_on then
     select * into strict shared_price from staff_ai_quota_private.prices where model=pol.model;
     shared_bound:=greatest(ub,(pol.max_input_tokens*shared_price.input_usd_million+
       pol.max_output_tokens*shared_price.output_usd_million)/1000000);
     if p_stage='reserve' then
       shared_ticket:=staff_ai_quota_private.reserve('mission_generic_ai',r.id,1,
         w.master_session_id,pol.model,shared_bound);
       if shared_ticket->>'granted_now'<>'true' then
         raise exception 'STAFF_GENERIC_RESERVE_REPLAY' using errcode='40001';
       end if;
     elsif not exists(select 1 from staff_ai_quota_private.calls c where
       c.producer='mission_generic_ai' and c.source_id=r.id and c.call_no=1
       and c.scope_id=w.master_session_id and c.state='reserved') then
       raise exception 'STAFF_GENERIC_RESERVE_MISSING' using errcode='40001';
     end if;
   else
   -- Budget Staff Test Room: 1000 chiamate e 5 USD nella finestra mobile di 30 giorni.
   -- La classificazione storica non dipende dallo stato aperto della sessione.
   select coalesce(sum(cost),0),count(*) filter(where used)
     into staff_spent,staff_calls
   from (
     select d.id,d.master_session_id,d.created_at,
       case when d.status in('success','fallback','unknown_billable')
         then coalesce(d.charged_cost_usd,d.upper_bound_cost_usd,0)
         else coalesce(d.upper_bound_cost_usd,0) end as cost,
       exists(select 1 from mission_narrative_internal.dispatch_attempts t where t.receipt_id=d.id) as used
     from mission_narrative_internal.dispatch_receipts d
     join public.master_v2_sessions s on s.id=d.master_session_id
     where d.event_kind='mission_generic_event'
       and d.renderer_version='mission-generic-runtime/1'
       and d.created_at>=clock_timestamp()-interval '30 days'
       and s.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid
       and s.owner_kind='ai_service'
   ) staff_receipts;
   if staff_spent+extra>5::numeric or (NOT (mission_generic_owner.manual_staff_count_limit_v1(w.master_session_id)='none') AND staff_calls+extra_call>1000)
   then raise exception 'MGPG_STAFF_ROLLING_BUDGET_EXHAUSTED';end if;
   end if;
 else
   if day_spent+extra>g.daily_budget_usd or all_spent+extra>g.global_budget_usd
     or (NOT (mission_generic_owner.manual_staff_count_limit_v1(w.master_session_id)='none') AND(day_calls+extra_call>g.max_daily_calls or all_calls+extra_call>g.max_global_calls))
   then raise exception 'MGPG_BUDGET_EXHAUSTED';end if;
 end if;
end;
$function$

mission_generic_owner__provider_ready.sq.source:
CREATE OR REPLACE FUNCTION mission_generic_owner.provider_ready(p_work uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w mission_generic_owner.work_items;a mission_generic_owner.dispatch_admissions;
 g mission_generic_owner.provider_policy;
begin
 perform mission_ai_board_owner.service_only();
 select * into strict w from mission_generic_owner.work_items where id=p_work;
 perform mission_generic_owner.work_assert(w);
 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) AND (mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true) IS NULL OR mission_generic_owner.flow_scope_enabled(w.master_session_id) IS DISTINCT FROM TRUE) THEN RAISE EXCEPTION 'C1266_PROVIDER5_CLOSED' USING ERRCODE='42501';END IF;
 select * into strict g from mission_generic_owner.provider_policy where singleton for share;
 select * into strict a from mission_generic_owner.dispatch_admissions where master_session_id=w.master_session_id;
 if not g.enabled or not a.enabled or (not mission_academy_owner.staff_carrier_runtime(w.master_session_id)
 and mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NULL and ((NOT (mission_generic_owner.manual_staff_count_limit_v1(w.master_session_id)='none') AND(a.call_limit>g.max_run_calls OR a.calls_authorized>a.call_limit)) OR a.cost_budget_usd>g.run_budget_usd))
 then raise exception 'MGPG_CLOSED_OR_ADMISSION';end if;
 if a.c7_budget_enforced and a.c7_budget_qualification_sha256 is null then raise exception 'MGPG_C7_BUDGET_UNQUALIFIED' using errcode='55000';end if;
end;
$function$

public__mission_generic_dispatch_authori.source:
CREATE OR REPLACE FUNCTION public.mission_generic_dispatch_authorize_v1(p_work uuid, p_lease uuid, p_worker_token text, p_policy jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w mission_generic_owner.work_items;a mission_generic_owner.dispatch_admissions;pol mission_narrative_internal.runtime_policy;
 rr jsonb;z jsonb;spent numeric;ub numeric;c8_proof jsonb;
begin
 perform mission_ai_board_owner.service_only();
 -- C1266_AVAILABILITY_COORD: shared before mutation locks; xact lifetime.
 PERFORM pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0));

 -- C9: freeze policy DML through proof, Native reserve and authorization.
 LOCK TABLE mission_narrative_internal.runtime_policy IN SHARE MODE;
 perform 1 from mission_generic_owner.role_window_cursors
   where master_session_id=(select master_session_id from mission_generic_owner.work_items where id=p_work)
   for update;
 if (select master_session_id from mission_generic_owner.work_items where id=p_work)
   ='b70b23cf-bad8-475d-a56a-d9c549e35d84'::uuid and not found
 then raise exception 'MRS_V4_CURSOR_REQUIRED' using errcode='40001';end if;
 perform 1 from public.master_v2_sessions where id=(select master_session_id from mission_generic_owner.work_items where id=p_work) for update;
 select * into strict w from mission_generic_owner.work_items where id=p_work for update; perform mission_generic_owner.role_dispatch_assert_v4(w.id);
 perform mission_generic_owner.work_assert(w);
 perform mission_generic_owner.assert_runtime(w.master_session_id);
 IF mission_generic_owner.c1266_opening_named_v1(w.master_session_id) AND mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true) IS NULL THEN RAISE EXCEPTION 'C1266_AUTHORIZE5_CLOSED' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM public.master_v2_sessions s726 WHERE s726.id=w.master_session_id AND s726.owner_kind='ai_service' AND s726.location_id='0b85f354-9cdb-47e1-baf9-3d266bb7e06b'::uuid AND (EXISTS(SELECT 1 FROM mission_generic_owner.flow_staff_sessions f726 WHERE f726.master_session_id=s726.id AND f726.enabled) OR EXISTS(SELECT 1 FROM mission_factory_owner.quest_run_sources q726 WHERE q726.session_id=s726.id AND q726.availability_scope='staff' AND q726.execution_context='staff_simulation'))) AND NOT mission_academy_owner.staff_carrier_runtime(w.master_session_id) AND NOT mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id) THEN RAISE EXCEPTION 'C726_FACTORY_STAFF_SCOPE_CLOSED' USING ERRCODE='42501';END IF;

 if w.state<>'claimed' or w.lease_id<>p_lease or w.lease_expires_at<=clock_timestamp()
 or p_policy->>'payload_sha256' is distinct from w.payload_sha256 then raise exception 'MGD_AUTHORIZE_STALE';end if;
 select * into strict a from mission_generic_owner.dispatch_admissions where master_session_id=w.master_session_id for update;
 select * into strict pol from mission_narrative_internal.runtime_policy where singleton;
 if not a.enabled or (not mission_academy_owner.staff_carrier_runtime(w.master_session_id) and mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NULL and NOT (mission_generic_owner.manual_staff_count_limit_v1(w.master_session_id)='none') and a.calls_authorized>=a.call_limit) or p_policy->>'model' is distinct from pol.model
 or p_policy->>'reasoning_effort' is distinct from pol.reasoning_effort or p_policy->>'store' is distinct from 'false'
 or (p_policy->>'max_output_tokens')::integer is distinct from pol.max_output_tokens then raise exception 'MGD_ADMISSION_INVALID';end if;
 if a.c7_budget_enforced then c8_proof:=mission_generic_owner.c8_input_proof_assert_v1(w.id,p_lease,p_policy);end if;
 pol.max_input_tokens:=mission_generic_owner.receipt_input_cap(w.dispatch_receipt_id,pol.max_input_tokens);
 ub:=(pol.max_input_tokens*pol.input_usd_million+pol.max_output_tokens*pol.output_usd_million)/1000000;
 select coalesce(sum(case when d.status in('success','fallback','unknown_billable') then coalesce(d.charged_cost_usd,0)
  else coalesce(d.upper_bound_cost_usd,0) end),0) into spent
 from mission_narrative_internal.dispatch_receipts d where d.master_session_id=w.master_session_id;
 if not mission_academy_owner.staff_carrier_runtime(w.master_session_id) and mission_generic_owner.c1266_staff_scene_policy_v1(w.master_session_id) IS NULL and spent+ub>a.cost_budget_usd
 then raise exception 'MGD_RUN_BUDGET_EXHAUSTED';end if;
 perform mission_generic_owner.provider_permit(w.id,'authorize');
 -- Count and Gen have independent budgets. Native Gen lease stays within the work lease.
 if mission_generic_owner.c1266_clean_staff_admission_v1(w.master_session_id,true,true) IS NOT NULL
 OR (mission_generic_owner.c1266_opening_named_v1(w.master_session_id) AND mission_generic_owner.c1266_execution_authority_v1(w.master_session_id,false,true) IS NOT NULL) then
  if extract(epoch from(w.lease_expires_at-clock_timestamp()))<30 then
   raise exception 'C1266_BACKGROUND_GENERATION_DEADLINE_CLOSED' using errcode='55000';end if;
  rr:=public.mission_narrative_attempt_reserve_internal(p_worker_token,w.dispatch_receipt_id,
   least(260,floor(extract(epoch from(w.lease_expires_at-clock_timestamp())))::integer),null,null);
 else
  rr:=public.mission_narrative_attempt_reserve_internal(p_worker_token,w.dispatch_receipt_id,180,null,null);
 end if;
 if rr->>'status'<>'reserved' then raise exception 'MGD_NATIVE_RESERVE_REJECTED';end if;
 z:=public.mission_narrative_provider_authorize_internal(p_worker_token,w.dispatch_receipt_id,(rr->>'attempt_id')::uuid,rr->>'lease_token');
 if not mission_academy_owner.staff_carrier_runtime(w.master_session_id) then
   update mission_generic_owner.dispatch_admissions set calls_authorized=calls_authorized+1,manual_count_limit=CASE WHEN mission_generic_owner.manual_staff_count_limit_v1(w.master_session_id)='none' THEN 'none' ELSE manual_count_limit END where master_session_id=w.master_session_id;
 end if;
 update mission_generic_owner.work_items set state='authorized',authorization_id=(z->>'authorization_id')::uuid where id=w.id;
 return z||jsonb_build_object('work_id',w.id,'granted_now',true)||case when c8_proof is not null then jsonb_build_object('input_measurement_id',c8_proof->>'measurement_id','provider_request_sha256',c8_proof->>'generation_request_sha256','policy_snapshot_sha256',c8_proof->>'policy_snapshot_sha256') else '{}'::jsonb end;
end;
$function$

public__mission_generic_dispatch_claim_v.source:
CREATE OR REPLACE FUNCTION public.mission_generic_dispatch_claim_v1(p_user uuid, p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare named_clean48 boolean:=false;w mission_generic_owner.work_items;a mission_generic_owner.dispatch_admissions;pol mission_narrative_internal.runtime_policy;
 d mission_narrative_internal.dispatch_receipts;
 dr uuid;env jsonb;fp text;limits jsonb;staff_calls bigint; narrative_contract jsonb;c7_budget jsonb;
c26_proof jsonb;c5_proof jsonb;campaign_scope boolean;observed jsonb;
begin
 perform mission_ai_board_owner.service_only();
 -- C1266_AVAILABILITY_COORD: shared before mutation locks; xact lifetime.
 PERFORM pg_catalog.pg_advisory_xact_lock_shared(pg_catalog.hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0));

 -- C9: freeze policy DML through proof, Native reserve and authorization.
 LOCK TABLE mission_narrative_internal.runtime_policy IN SHARE MODE;
 perform mission_generic_owner.dispatch_user((p_request->>'master_session_id')::uuid,p_user);
 if (p_request->>'master_session_id')='b70b23cf-bad8-475d-a56a-d9c549e35d84' then
   raise exception 'MRS_STAFF_SUNA_TICK_PAUSED' using errcode='55000';
 end if;
 perform 1 from mission_generic_owner.role_window_cursors
   where master_session_id=(p_request->>'master_session_id')::uuid for update;
 perform 1 from public.master_v2_sessions where id=(p_request->>'master_session_id')::uuid for update;
 select * into strict w from mission_generic_owner.work_items where master_session_id=(p_request->>'master_session_id')::uuid
 and event_id=(p_request->>'event_id')::uuid and request_key=(p_request->>'request_key')::uuid and revision=(p_request->>'expected_revision')::bigint for update;
 if mission_generic_owner.count_overflow_terminal_v1(w.id,p_user) then return jsonb_build_object('state','failed','granted_now',false);end if;
 campaign_scope:=NOT EXISTS(SELECT 1 FROM mission_generic_owner.manual_staff_admissions_v1 ma WHERE ma.master_session_id=w.master_session_id) AND (EXISTS(SELECT 1 FROM mission_public_owner.work_contracts_v1 sticky_wc
 WHERE sticky_wc.master_session_id=w.master_session_id AND sticky_wc.scope='staff_mission'
 AND sticky_wc.contract_sha256=public.combat_v2_sha256(sticky_wc.contract)
 AND sticky_wc.contract->>'schema_version'='mission-narrative-admission/3'
 AND sticky_wc.contract->'features' ? 'execution_authority_v1'
 AND (sticky_wc.contract#>>'{source_attestation,execution_authority,schema_version}'='c1266-work-execution-attestation/1' OR ((mission_generic_owner.c1266_historical_work_v1(sticky_wc.work_id)->>'schema_version'='c1266-work-execution-attestation/2') AND sticky_wc.contract#>'{source_attestation,execution_authority}'=mission_generic_owner.c1266_historical_work_v1(sticky_wc.work_id)))
 AND sticky_wc.contract#>>'{source_attestation,execution_authority,execution_context}'='staff_mission'
