 IF c5_proof IS NOT NULL AND c5_proof#>>'{admission,kind}'='staff_finite' AND NOT ((mission_factory_owner.keys_exact_v2(c5_proof->'admission',ARRAY['schema_version','kind','resource_scope','finite_admission_sha256','grant_id','not_before','expires_at','location_id','campaign_id','time_policy']) AND c5_proof->'admission'->>'schema_version'='c1266-staff-admission-authority/2' AND c5_proof->'admission'->>'kind'='staff_finite' AND c5_proof->'admission'->>'resource_scope'='staff_simulation' AND c5_proof->'admission'->>'campaign_id'='b2fc5e28-072b-41f2-8dd8-cb5a35a13092' AND c5_proof->'admission'->>'grant_id'='b925043a-c1b3-434b-8fb4-f335903b2af0' AND c5_proof->'admission'->>'not_before'='2026-10-20T14:12:18.393948+00:00' AND c5_proof->'admission'->>'expires_at'='2026-10-20T15:12:18.393948+00:00' AND c5_proof->'admission'->>'location_id'='0b85f354-9cdb-47e1-baf9-3d266bb7e06b' AND c5_proof->'admission'->'time_policy'='{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}'::jsonb AND (c5_proof->'admission'->>'finite_admission_sha256' ~ '^[a-f0-9]{64}$') IS TRUE) IS TRUE) AND
 (c5_proof#>>'{admission,expires_at}')::timestamptz<=clock_timestamp()+interval '360 seconds'
 THEN RAISE EXCEPTION 'C1266_BACKGROUND_DEADLINE_CLOSED' USING ERRCODE='55000';END IF;
 update mission_generic_owner.work_items set state='claimed',dispatch_receipt_id=dr,lease_id=gen_random_uuid(),
  lease_expires_at=CASE WHEN c5_proof#>>'{admission,schema_version}'='c1266-staff-admission-authority/3' THEN clock_timestamp()+interval '360 seconds' WHEN c26_proof IS NOT NULL THEN CASE WHEN named_clean48 THEN clock_timestamp()+interval '360 seconds' ELSE least(clock_timestamp()+interval '360 seconds',(c26_proof#>>'{admission_attestation,expires_at}')::timestamptz) END WHEN c5_proof IS NOT NULL THEN CASE WHEN ((mission_factory_owner.keys_exact_v2(c5_proof->'admission',ARRAY['schema_version','kind','resource_scope','finite_admission_sha256','grant_id','not_before','expires_at','location_id','campaign_id','time_policy']) AND c5_proof->'admission'->>'schema_version'='c1266-staff-admission-authority/2' AND c5_proof->'admission'->>'kind'='staff_finite' AND c5_proof->'admission'->>'resource_scope'='staff_simulation' AND c5_proof->'admission'->>'campaign_id'='b2fc5e28-072b-41f2-8dd8-cb5a35a13092' AND c5_proof->'admission'->>'grant_id'='b925043a-c1b3-434b-8fb4-f335903b2af0' AND c5_proof->'admission'->>'not_before'='2026-10-20T14:12:18.393948+00:00' AND c5_proof->'admission'->>'expires_at'='2026-10-20T15:12:18.393948+00:00' AND c5_proof->'admission'->>'location_id'='0b85f354-9cdb-47e1-baf9-3d266bb7e06b' AND c5_proof->'admission'->'time_policy'='{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}'::jsonb AND (c5_proof->'admission'->>'finite_admission_sha256' ~ '^[a-f0-9]{64}$') IS TRUE) IS TRUE) THEN clock_timestamp()+interval '360 seconds' ELSE CASE WHEN c5_proof#>>'{admission,kind}'='staff_finite' THEN least(clock_timestamp()+interval '360 seconds',(c5_proof#>>'{admission,expires_at}')::timestamptz) ELSE clock_timestamp()+interval '360 seconds' END END ELSE clock_timestamp()+interval '180 seconds' END where id=w.id returning * into w;
 IF c7_budget->>'campaign_time_mode'='budget_or_explicit_stop' THEN
   IF NOT ((mission_factory_owner.keys_exact_v2(c5_proof->'admission',ARRAY['schema_version','kind','resource_scope','finite_admission_sha256','grant_id','not_before','expires_at','location_id','campaign_id','time_policy']) AND c5_proof->'admission'->>'schema_version'='c1266-staff-admission-authority/2' AND c5_proof->'admission'->>'kind'='staff_finite' AND c5_proof->'admission'->>'resource_scope'='staff_simulation' AND c5_proof->'admission'->>'campaign_id'='b2fc5e28-072b-41f2-8dd8-cb5a35a13092' AND c5_proof->'admission'->>'grant_id'='b925043a-c1b3-434b-8fb4-f335903b2af0' AND c5_proof->'admission'->>'not_before'='2026-10-20T14:12:18.393948+00:00' AND c5_proof->'admission'->>'expires_at'='2026-10-20T15:12:18.393948+00:00' AND c5_proof->'admission'->>'location_id'='0b85f354-9cdb-47e1-baf9-3d266bb7e06b' AND c5_proof->'admission'->'time_policy'='{"mode":"budget_or_explicit_stop","expires_at_role":"historical_provenance"}'::jsonb AND (c5_proof->'admission'->>'finite_admission_sha256' ~ '^[a-f0-9]{64}$') IS TRUE) IS TRUE) OR c7_budget->'campaign_provider_deadline' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'C1266_NAMED47_LEASE_POLICY_CLOSED' USING ERRCODE='42501';END IF;
  ELSIF c7_budget ? 'campaign_provider_deadline' THEN
  UPDATE mission_generic_owner.work_items SET lease_expires_at=least(lease_expires_at,(c7_budget->>'campaign_provider_deadline')::timestamptz) WHERE id=w.id RETURNING * INTO w;
 END IF;
 return jsonb_build_object('state','claimed','granted_now',true,'work',jsonb_build_object('schema_version','mission-generic-work/1',
  'work_id',w.id,'master_session_id',w.master_session_id,'event_id',w.event_id,'request_key',w.request_key,'revision',w.revision,
  'step_key',w.step_key,'run_control_version',w.run_control_version,'definition_sha256',w.definition_sha256,
  'encounter_id',w.encounter_id,'authority_receipt_id',w.authority_receipt_id,'kind',w.kind,'lease_id',w.lease_id,
  'server_now',clock_timestamp(),'lease_expires_at',w.lease_expires_at,'payload_sha256',w.payload_sha256,'payload',w.payload,'limits',limits,
  'narrative_admission',narrative_contract,'narrative_admission_sha256',case when narrative_contract is not null then public.combat_v2_sha256(narrative_contract) end,
   'provider_input_contract',case when c5_proof IS NOT NULL THEN mission_generic_owner.c1266_provider_input_v1(w.id,limits) ELSE case when c26_proof IS NOT NULL then jsonb_build_object(
 'schema_version','mission-generic-provider-input/4','input_tokens_limit',24000,'policy_version',pol.policy_version,'http_calls_per_generation',2,
 'scope',jsonb_build_object('schema_version','c1266-clean-staff-work-scope/1','execution_context','staff_mission',
 'master_session_id',w.master_session_id,'work_id',w.id,'event_id',w.event_id,'request_key',w.request_key,'revision',w.revision,
 'authority_receipt_id',w.authority_receipt_id,'definition_sha256',w.definition_sha256,'payload_sha256',w.payload_sha256,
 'payload_schema_version',w.payload->>'schema_version','run_control_version',w.run_control_version,
 'narrative_admission_sha256',case when narrative_contract is not null then public.combat_v2_sha256(narrative_contract) end,
 'release_sha256',c26_proof->>'release_sha256','finite_admission_sha256',c26_proof->>'finite_admission_sha256',
 'policy_snapshot_sha256',public.combat_v2_sha256(mission_generic_owner.c8_policy_snapshot_v1(w.id)),
 'financial_qualification_sha256',a.c8_count_qualification_sha256),
 'pricing',jsonb_build_object('model',pol.model,'reasoning_effort',pol.reasoning_effort,'store',pol.store,
 'max_output_tokens',limits->'max_output_tokens','input_usd_million',pol.input_usd_million,'output_usd_million',pol.output_usd_million,
 'count_upper_cost_usd','0.0124','generation_upper_cost_usd','0.0124'),
 'byte_bounds',jsonb_build_object('max_input_bytes',limits->'max_input_bytes','max_request_bytes',limits->'max_request_bytes')) else case when a.c7_budget_enforced then case when mission_generic_owner.c8_context24_scope_v1(w.id) then jsonb_build_object('schema_version','mission-generic-provider-input/3','input_tokens_limit',24000,'policy_version',pol.policy_version,'http_calls_per_generation',2,'scope',jsonb_build_object('schema_version','c889-context24-work-scope/1','session_id',w.master_session_id,'work_id',w.id,'batch_id',w.authority_receipt_id,'old_work_id','c88958e7-8983-4332-a14e-095076f967f4','financial_qualification_sha256',a.c8_count_qualification_sha256,'count_reserve_usd','0.0124','generation_reserve_usd','0.0124'),'pricing',jsonb_build_object('model',pol.model,'reasoning_effort',pol.reasoning_effort,'store',pol.store,'max_output_tokens',20000,'input_usd_million',pol.input_usd_million,'output_usd_million',pol.output_usd_million,'count_upper_cost_usd','0.0124','generation_upper_cost_usd','0.0124'),'byte_bounds',jsonb_build_object('max_input_bytes',limits->'max_input_bytes','max_request_bytes',limits->'max_request_bytes')) else jsonb_build_object('schema_version','mission-generic-provider-input/1','input_tokens_limit',(select max_input_tokens from mission_narrative_internal.runtime_policy where singleton),'policy_version',pol.policy_version,'http_calls_per_generation',2)  end else null end end end,
  'narrative_profile',case when narrative_contract is not null then narrative_contract->>'editorial_profile' when w.kind in('narration','director') and (mission_academy_owner.staff_carrier_runtime(w.master_session_id) OR mission_generic_owner.c726_factory_staff_runtime_v1(w.master_session_id))
    then 'cinematic_master_1' else 'legacy' end) - case when not a.c7_budget_enforced then 'provider_input_contract' else '__no_key__' end);
end $function$

public__mission_generic_staff_tick_v1.sq.source:
CREATE OR REPLACE FUNCTION public.mission_generic_staff_tick_v1(p_session uuid, p_user uuid, p_source_revision text, p_staff uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE tick mission_generic_owner.staff_progress_ticks_v1;
        m public.master_v2_sessions; r public.mission_run_state;
        diag jsonb; pending jsonb; result jsonb; new_key uuid;
        terminal boolean; mb_admission mission_generic_owner.dispatch_admissions;mb_budget jsonb;mb_flow boolean;mb_http bigint;
BEGIN
  PERFORM mission_ai_board_owner.service_only();
  IF p_session IS NULL OR p_user IS NULL OR p_staff IS NULL
    OR p_source_revision IS NULL OR p_source_revision !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'MGS_TICK_ARGUMENTS' USING ERRCODE='22023'; END IF;
  -- L'Edge deve verificare la sessione utente; il DB ricontrolla ruolo Staff.
  IF NOT EXISTS (SELECT 1 FROM public.profiles p WHERE p.id=p_staff AND p.role IN ('admin','master'))
  THEN RAISE EXCEPTION 'MGS_TICK_STAFF_REQUIRED' USING ERRCODE='42501'; END IF;
  -- Il capture del submit e il tick serializzano sullo stesso cursore prima
  -- che la role sia acquisita/pubblicata. Master non va bloccato prima.
  PERFORM 1 FROM mission_generic_owner.role_window_cursors c
    WHERE c.master_session_id=p_session FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MGS_TICK_CURSOR_REQUIRED' USING ERRCODE='55000'; END IF;
  PERFORM public.master_v2_lock_scope(p_session);
  SELECT s.* INTO STRICT m FROM public.master_v2_sessions s WHERE s.id=p_session FOR UPDATE;
  SELECT s.* INTO STRICT r FROM public.mission_run_state s WHERE s.master_session_id=p_session FOR UPDATE;
  -- One named repair of a paused, immutable, no-dispatch receipt; no provider or source reset.
  IF p_source_revision='24db5db8da7ede254e6d719b587c4fa04dce6b9d1c920396251adb85d0f6294c' AND p_user='b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid AND p_staff=p_user AND (p_session='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND mission_generic_owner.manual_staff_count_limit_v1(p_session)='none'
 AND EXISTS(SELECT 1 FROM mission_generic_owner.staff_progress_ticks_v1 bt JOIN mission_generic_owner.progress_receipts bp ON bp.request_key=bt.request_key AND bp.master_session_id=bt.master_session_id AND bp.actor_user_id=bt.actor_user_id AND bp.result_sha256=bt.result_sha256 AND bp.result_sha256=public.combat_v2_sha256(bp.result)
 WHERE bt.master_session_id=p_session AND bt.request_key='9e48a416-9261-4399-9e4e-a82b8a3d3a48'::uuid AND bt.source_revision='24db5db8da7ede254e6d719b587c4fa04dce6b9d1c920396251adb85d0f6294c' AND bt.actor_user_id='b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid AND bt.staff_user_id=bt.actor_user_id AND bt.result_sha256='b27ed0db18a45d371931f015be0cd0fa060ed3f99b8d5843e8cbef45ecfbb2f8'
 AND mission_factory_owner.keys_exact_v2(bp.result,ARRAY['schema_version','master_session_id','state','dispatch','reason_code']) AND bp.result->>'schema_version'='mission-generic-progress/1' AND bp.result->>'master_session_id'=p_session::text AND bp.result->>'state'='paused' AND bp.result->>'reason_code'='MGPG_C7_RUN_BUDGET_STOP' AND bp.result->'dispatch'='null'::jsonb)) THEN
   IF mission_generic_owner.role_source_revision_v1(p_session) IS DISTINCT FROM p_source_revision
    OR (NOT EXISTS(SELECT 1 FROM mission_generic_owner.progress_receipts done_pr WHERE done_pr.request_key=mission_ai_service_owner.uuid5('9e48a416-9261-4399-9e4e-a82b8a3d3a48'::uuid,'mission-staff-budget-only-resume/1:'||'24db5db8da7ede254e6d719b587c4fa04dce6b9d1c920396251adb85d0f6294c') AND done_pr.master_session_id=p_session AND done_pr.actor_user_id=p_user AND done_pr.result_sha256=public.combat_v2_sha256(done_pr.result)) AND (EXISTS(SELECT 1 FROM mission_generic_owner.work_items wi WHERE wi.master_session_id=p_session AND wi.state IN('ready','claimed','authorized','provider_started','uncertain'))
    OR EXISTS(SELECT 1 FROM mission_generic_owner.unified_source_windows sw WHERE sw.master_session_id=p_session AND sw.superseded_at IS NULL AND sw.consumed_message_id IS NULL)
    OR EXISTS(SELECT 1 FROM public.combat_v2_sessions cs WHERE cs.master_session_id=p_session AND cs.closed_at IS NULL)))
    OR NOT EXISTS(SELECT 1 FROM public.master_v2_participants mp WHERE mp.session_id=p_session AND mp.user_id_snapshot=p_user AND mp.left_at IS NULL)
   THEN RAISE EXCEPTION 'MANUAL_BUDGET_RECOVERY_SOURCE_CHANGED' USING ERRCODE='40001';END IF;
   new_key:=mission_ai_service_owner.uuid5('9e48a416-9261-4399-9e4e-a82b8a3d3a48'::uuid,'mission-staff-budget-only-resume/1:'||'24db5db8da7ede254e6d719b587c4fa04dce6b9d1c920396251adb85d0f6294c');
   SELECT pr.result INTO result FROM mission_generic_owner.progress_receipts pr WHERE pr.request_key=new_key AND pr.master_session_id=p_session AND pr.actor_user_id=p_user AND pr.result_sha256=public.combat_v2_sha256(pr.result);
   IF FOUND THEN RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1','state','replayed','source_revision',p_source_revision,'request_key',new_key,'progress',result);END IF;
   SELECT * INTO STRICT mb_admission FROM mission_generic_owner.dispatch_admissions WHERE master_session_id=p_session FOR UPDATE;
   SELECT enabled INTO STRICT mb_flow FROM mission_generic_owner.flow_staff_sessions WHERE master_session_id=p_session FOR UPDATE;
   SELECT coalesce(sum((CASE WHEN ca.details IS NOT NULL THEN 1 ELSE 0 END)+(CASE WHEN d.upper_bound_cost_usd IS NOT NULL OR EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_attempts da WHERE da.receipt_id=d.id) THEN 1 ELSE 0 END)),0) INTO mb_http
   FROM mission_generic_owner.work_items wi LEFT JOIN mission_narrative_internal.dispatch_receipts d ON d.id=wi.dispatch_receipt_id LEFT JOIN mission_narrative_internal.dispatch_audit ca ON ca.receipt_id=d.id AND ca.event_code='c8_count_started' WHERE wi.master_session_id=p_session;
   IF NOT mb_admission.enabled AND NOT mb_flow AND mb_admission.call_limit=14 AND mb_admission.calls_authorized=0 AND mb_http=28 AND mb_admission.c7_budget_enforced AND mb_admission.cost_budget_usd=0.3136 THEN
    UPDATE mission_generic_owner.dispatch_admissions SET enabled=true,manual_count_limit='none' WHERE master_session_id=p_session;
    UPDATE mission_generic_owner.flow_staff_sessions SET enabled=true WHERE master_session_id=p_session;
   ELSIF NOT(mb_admission.enabled AND mb_flow AND EXISTS(SELECT 1 FROM public.mission_run_audit ma WHERE ma.master_session_id=p_session AND ma.event_code='manual_staff_budget_only_reenabled' AND ma.metadata->>'original_request_key'='9e48a416-9261-4399-9e4e-a82b8a3d3a48' AND ma.metadata->>'original_result_sha256'='b27ed0db18a45d371931f015be0cd0fa060ed3f99b8d5843e8cbef45ecfbb2f8')) THEN RAISE EXCEPTION 'MANUAL_BUDGET_RECOVERY_ADMISSION_PROOF';END IF;
   mb_budget:=mission_generic_owner.c7_run_budget_v1(p_session,true,NULL);
   IF (mb_budget->>'allowed') IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'MANUAL_BUDGET_RECOVERY_MONEY_CLOSED' USING ERRCODE='55000';END IF;
   IF NOT EXISTS(SELECT 1 FROM public.mission_run_audit ma WHERE ma.master_session_id=p_session AND ma.event_code='manual_staff_budget_only_reenabled' AND ma.metadata->>'original_request_key'='9e48a416-9261-4399-9e4e-a82b8a3d3a48' AND ma.metadata->>'original_result_sha256'='b27ed0db18a45d371931f015be0cd0fa060ed3f99b8d5843e8cbef45ecfbb2f8') THEN
    INSERT INTO public.mission_run_audit(master_session_id,event_id,event_code,metadata,created_at)VALUES(p_session,NULL,'manual_staff_budget_only_reenabled',jsonb_build_object('schema_version','manual-staff-budget-only-reenable/1','original_request_key','9e48a416-9261-4399-9e4e-a82b8a3d3a48','original_result_sha256','b27ed0db18a45d371931f015be0cd0fa060ed3f99b8d5843e8cbef45ecfbb2f8','source_revision',p_source_revision,'successor_request_key',new_key,'actor_user_id',p_user,'call_limit',mb_admission.call_limit,'calls_authorized',mb_admission.calls_authorized,'spent_usd',mb_budget->'spent_usd','cost_budget_usd',mb_admission.cost_budget_usd,'generation_http_calls',0,'history_preserved',true),clock_timestamp());
   END IF;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM mission_generic_owner.flow_staff_sessions f
    JOIN public.locations l ON l.id=m.location_id
    WHERE f.master_session_id=p_session AND f.enabled AND l.is_test)
    OR m.owner_kind<>'ai_service' OR m.closed_at IS NOT NULL
    OR m.stato<>'in_corso' OR m.suspended_at IS NOT NULL OR r.run_phase<>'in_corso'
    OR NOT mission_generic_owner.flow_scope_enabled(p_session)
  THEN RAISE EXCEPTION 'MGS_TICK_SCOPE' USING ERRCODE='42501'; END IF;
  PERFORM mission_generic_owner.dispatch_user(p_session,p_user);
  -- Anche il replay deve appartenere alla revisione ancora corrente: un nuovo
  -- Fato o una nuova role non possono riesporre un vecchio dispatch.
  diag:=mission_generic_owner.role_flow_status_v1(p_session,p_user);
  IF diag->>'source_revision' IS DISTINCT FROM p_source_revision
    OR mission_generic_owner.role_source_revision_v1(p_session) IS DISTINCT FROM p_source_revision
  THEN RAISE EXCEPTION 'MGS_TICK_SOURCE_CHANGED' USING ERRCODE='40001'; END IF;
  SELECT * INTO tick FROM mission_generic_owner.staff_progress_ticks_v1
    WHERE master_session_id=p_session AND source_revision=p_source_revision FOR UPDATE;
  IF tick.request_key IS NOT NULL THEN
    IF tick.actor_user_id<>p_user THEN RAISE EXCEPTION 'MGS_TICK_ACTOR_CONFLICT' USING ERRCODE='40001'; END IF;
    IF p_session='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND p_source_revision='ac9aedbd59dcb835d717f4ddb6ce195e3c2a9d640df576667290fa38b7e6cbbb' AND mission_generic_owner.role_source_released_v4('433ace05-5265-4aad-96a3-5567b6e3480a'::uuid) THEN
     SELECT pr.result INTO result FROM mission_generic_owner.progress_receipts pr WHERE pr.request_key=mission_ai_service_owner.uuid5('310493d3-92d2-4645-ba85-ab42f57dbf9d'::uuid,'mission-staff-unpublished-reinterpretation/1:ac9aedbd59dcb835d717f4ddb6ce195e3c2a9d640df576667290fa38b7e6cbbb') AND pr.master_session_id=p_session AND pr.actor_user_id=p_user AND pr.result_sha256=public.combat_v2_sha256(pr.result);
     IF FOUND THEN RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1','state','replayed','source_revision',p_source_revision,'request_key',mission_ai_service_owner.uuid5('310493d3-92d2-4645-ba85-ab42f57dbf9d'::uuid,'mission-staff-unpublished-reinterpretation/1:ac9aedbd59dcb835d717f4ddb6ce195e3c2a9d640df576667290fa38b7e6cbbb'),'progress',result);END IF;
    END IF;

    SELECT pr.result INTO STRICT result FROM mission_generic_owner.progress_receipts pr
      WHERE pr.request_key=tick.request_key AND pr.master_session_id=p_session
        AND pr.actor_user_id=p_user AND pr.result_sha256=tick.result_sha256
        AND pr.result_sha256=public.combat_v2_sha256(pr.result);
    IF tick.request_key='9e48a416-9261-4399-9e4e-a82b8a3d3a48'::uuid AND p_source_revision='24db5db8da7ede254e6d719b587c4fa04dce6b9d1c920396251adb85d0f6294c' AND (p_session='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND mission_generic_owner.manual_staff_count_limit_v1(p_session)='none'
 AND EXISTS(SELECT 1 FROM mission_generic_owner.staff_progress_ticks_v1 bt JOIN mission_generic_owner.progress_receipts bp ON bp.request_key=bt.request_key AND bp.master_session_id=bt.master_session_id AND bp.actor_user_id=bt.actor_user_id AND bp.result_sha256=bt.result_sha256 AND bp.result_sha256=public.combat_v2_sha256(bp.result)
 WHERE bt.master_session_id=p_session AND bt.request_key='9e48a416-9261-4399-9e4e-a82b8a3d3a48'::uuid AND bt.source_revision='24db5db8da7ede254e6d719b587c4fa04dce6b9d1c920396251adb85d0f6294c' AND bt.actor_user_id='b4952ed5-5ce0-49c0-9f2b-8fd5dcd89b4b'::uuid AND bt.staff_user_id=bt.actor_user_id AND bt.result_sha256='b27ed0db18a45d371931f015be0cd0fa060ed3f99b8d5843e8cbef45ecfbb2f8'
 AND mission_factory_owner.keys_exact_v2(bp.result,ARRAY['schema_version','master_session_id','state','dispatch','reason_code']) AND bp.result->>'schema_version'='mission-generic-progress/1' AND bp.result->>'master_session_id'=p_session::text AND bp.result->>'state'='paused' AND bp.result->>'reason_code'='MGPG_C7_RUN_BUDGET_STOP' AND bp.result->'dispatch'='null'::jsonb)) THEN
     new_key:=mission_ai_service_owner.uuid5(tick.request_key,'mission-staff-budget-only-resume/1:'||p_source_revision);
     SELECT pr.result INTO result FROM mission_generic_owner.progress_receipts pr WHERE pr.request_key=new_key AND pr.master_session_id=p_session AND pr.actor_user_id=p_user AND pr.result_sha256=public.combat_v2_sha256(pr.result);
     IF FOUND THEN RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1','state','replayed','source_revision',p_source_revision,'request_key',new_key,'progress',result);END IF;
     IF mission_generic_owner.role_flow_status_v1(p_session,p_user)->>'flow_reason' IS DISTINCT FROM 'ready_to_evaluate' THEN RAISE EXCEPTION 'MANUAL_BUDGET_RECOVERY_ROLE_NOT_READY';END IF;
     result:=mission_generic_owner.progress_step(p_session,p_user,new_key);
     IF jsonb_typeof(result->'dispatch') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'MANUAL_BUDGET_RECOVERY_NO_DISPATCH';END IF;
     INSERT INTO mission_generic_owner.progress_receipts(request_key,master_session_id,actor_user_id,result,result_sha256)VALUES(new_key,p_session,p_user,result,public.combat_v2_sha256(result));
     RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1','state','issued','source_revision',p_source_revision,'request_key',new_key,'progress',result);
    END IF;
    -- Immutable no-dispatch progress may acquire one server-owned successor receipt.
    IF (mission_factory_owner.keys_exact_v2(result,ARRAY['schema_version','master_session_id','state','dispatch'])
 AND result->>'schema_version'='mission-generic-progress/1' AND result->>'master_session_id'=p_session::text
 AND result->>'state'='needs_attention' AND result->'dispatch'='null'::jsonb
 AND EXISTS(SELECT 1 FROM mission_generic_owner.work_items healed 
 WHERE healed.master_session_id=p_session AND healed.created_at<tick.created_at AND (healed.kind='director' AND healed.state='failed' AND healed.result->>'ok'='true'
 AND healed.payload_sha256=public.combat_v2_sha256(healed.payload)
 AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts healed_dr
  JOIN mission_narrative_internal.dispatch_audit healed_a ON healed_a.receipt_id=healed_dr.id AND healed_a.event_code='c1266_saved_director_applied'
  JOIN mission_narrative_internal.dispatch_audit healed_f ON healed_f.receipt_id=healed_dr.id AND healed_f.event_code='generic_finalized'
  JOIN mission_generic_owner.unified_batches healed_b ON healed_b.decision_work_id=healed.id AND healed_b.master_session_id=p_session
  JOIN mission_generic_owner.unified_source_windows healed_s ON healed_s.id=healed_b.source_window_id AND healed_s.work_id=healed.id AND healed_s.master_session_id=p_session
  JOIN mission_generic_owner.work_items healed_writer ON healed_writer.id=healed_b.writer_work_id AND healed_writer.master_session_id=p_session AND healed_writer.authority_receipt_id=healed_b.id
  JOIN public.messages healed_msg ON healed_msg.id=healed_writer.message_id AND healed_msg.kind='fato' AND healed_msg.recipient_user IS NULL AND healed_msg.body=healed_writer.result->>'text'
  WHERE healed_dr.id=healed.dispatch_receipt_id AND healed_dr.master_session_id=p_session AND healed_dr.authority_receipt_id=healed.id AND healed_dr.request_key=healed.request_key
   AND healed_dr.status='success' AND healed_dr.dispatch_count=1 AND healed_dr.finalized_at IS NOT NULL
   AND healed_a.details->>'schema_version'='c1266-saved-director-application/1' AND healed_a.details->>'master_session_id'=p_session::text
   AND healed_a.details->>'work_id'=healed.id::text AND healed_a.details->>'result_sha256'=healed.result_sha256
   AND healed_a.details->>'batch_id'=healed_b.id::text AND healed_a.details->>'writer_work_id'=healed_writer.id::text
   AND healed_a.details->>'generation_http_calls'='0' AND healed_a.details->>'failed_work_preserved'='true'
   AND healed_f.details->>'work_id'=healed.id::text AND healed_f.details->>'receipt_id'=healed.receipt_id::text
   AND healed_f.details->>'result_sha256'=healed.result_sha256 AND healed_f.details->>'result_jsonb_sha256'=public.combat_v2_sha256(healed.result)
   AND healed_b.state='published' AND healed_b.published_at IS NOT NULL AND healed_b.message_id=healed_writer.message_id
   AND healed_s.consumed_message_id=healed_b.message_id AND healed_s.superseded_at IS NULL
   AND healed_s.source_sha256=healed.payload_sha256 AND healed_writer.kind='narration' AND healed_writer.state='completed'
   AND healed_writer.payload=healed_b.payload AND healed_writer.payload_sha256=healed_b.payload_sha256
   AND healed_writer.payload_sha256=public.combat_v2_sha256(healed_writer.payload)
   AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_segment_publications_v4 healed_pub WHERE healed_pub.work_id=healed_writer.id AND healed_pub.message_id=healed_msg.id)
   AND EXISTS(SELECT 1 FROM staff_ai_quota_private.calls healed_q WHERE healed_q.producer='mission_generic_ai' AND healed_q.scope_id=p_session AND healed_q.source_id=healed_dr.id AND healed_q.call_no=1 AND healed_q.state='settled' AND healed_q.charged_usd=healed_dr.charged_cost_usd)))) AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.work_items unresolved WHERE unresolved.master_session_id=p_session AND unresolved.step_key=r.current_step_key AND unresolved.run_control_version=r.control_version AND unresolved.state='failed' AND NOT (unresolved.kind='director' AND unresolved.state='failed' AND unresolved.result->>'ok'='true'
 AND unresolved.payload_sha256=public.combat_v2_sha256(unresolved.payload)
 AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts healed_dr
  JOIN mission_narrative_internal.dispatch_audit healed_a ON healed_a.receipt_id=healed_dr.id AND healed_a.event_code='c1266_saved_director_applied'
  JOIN mission_narrative_internal.dispatch_audit healed_f ON healed_f.receipt_id=healed_dr.id AND healed_f.event_code='generic_finalized'
  JOIN mission_generic_owner.unified_batches healed_b ON healed_b.decision_work_id=unresolved.id AND healed_b.master_session_id=p_session
  JOIN mission_generic_owner.unified_source_windows healed_s ON healed_s.id=healed_b.source_window_id AND healed_s.work_id=unresolved.id AND healed_s.master_session_id=p_session
  JOIN mission_generic_owner.work_items healed_writer ON healed_writer.id=healed_b.writer_work_id AND healed_writer.master_session_id=p_session AND healed_writer.authority_receipt_id=healed_b.id
  JOIN public.messages healed_msg ON healed_msg.id=healed_writer.message_id AND healed_msg.kind='fato' AND healed_msg.recipient_user IS NULL AND healed_msg.body=healed_writer.result->>'text'
  WHERE healed_dr.id=unresolved.dispatch_receipt_id AND healed_dr.master_session_id=p_session AND healed_dr.authority_receipt_id=unresolved.id AND healed_dr.request_key=unresolved.request_key
   AND healed_dr.status='success' AND healed_dr.dispatch_count=1 AND healed_dr.finalized_at IS NOT NULL
   AND healed_a.details->>'schema_version'='c1266-saved-director-application/1' AND healed_a.details->>'master_session_id'=p_session::text
   AND healed_a.details->>'work_id'=unresolved.id::text AND healed_a.details->>'result_sha256'=unresolved.result_sha256
   AND healed_a.details->>'batch_id'=healed_b.id::text AND healed_a.details->>'writer_work_id'=healed_writer.id::text
   AND healed_a.details->>'generation_http_calls'='0' AND healed_a.details->>'failed_work_preserved'='true'
   AND healed_f.details->>'work_id'=unresolved.id::text AND healed_f.details->>'receipt_id'=unresolved.receipt_id::text
   AND healed_f.details->>'result_sha256'=unresolved.result_sha256 AND healed_f.details->>'result_jsonb_sha256'=public.combat_v2_sha256(unresolved.result)
   AND healed_b.state='published' AND healed_b.published_at IS NOT NULL AND healed_b.message_id=healed_writer.message_id
   AND healed_s.consumed_message_id=healed_b.message_id AND healed_s.superseded_at IS NULL
   AND healed_s.source_sha256=unresolved.payload_sha256 AND healed_writer.kind='narration' AND healed_writer.state='completed'
   AND healed_writer.payload=healed_b.payload AND healed_writer.payload_sha256=healed_b.payload_sha256
   AND healed_writer.payload_sha256=public.combat_v2_sha256(healed_writer.payload)
   AND EXISTS(SELECT 1 FROM mission_generic_owner.unified_segment_publications_v4 healed_pub WHERE healed_pub.work_id=healed_writer.id AND healed_pub.message_id=healed_msg.id)
   AND EXISTS(SELECT 1 FROM staff_ai_quota_private.calls healed_q WHERE healed_q.producer='mission_generic_ai' AND healed_q.scope_id=p_session AND healed_q.source_id=healed_dr.id AND healed_q.call_no=1 AND healed_q.state='settled' AND healed_q.charged_usd=healed_dr.charged_cost_usd))) AND NOT EXISTS(SELECT 1 FROM mission_generic_owner.unified_source_windows released WHERE released.work_id=unresolved.id AND mission_generic_owner.role_source_released_v4(released.id)))) THEN
      new_key:=mission_ai_service_owner.uuid5(tick.request_key,'mission-staff-no-dispatch-resume/1:'||p_source_revision);
      SELECT pr.result INTO result FROM mission_generic_owner.progress_receipts pr WHERE pr.request_key=new_key
       AND pr.master_session_id=p_session AND pr.actor_user_id=p_user AND pr.result_sha256=public.combat_v2_sha256(pr.result);
      IF FOUND THEN RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1','state','replayed','source_revision',p_source_revision,'request_key',new_key,'progress',result);END IF;
      IF EXISTS(SELECT 1 FROM mission_generic_owner.progress_receipts pr WHERE pr.request_key=new_key) THEN RAISE EXCEPTION 'MGS_NO_WORK_RECEIPT_CONFLICT' USING ERRCODE='40001';END IF;
    ELSE
    -- The first tick is not rewritten. An attested, released Director may
    -- receive one deterministic retry for this very same role revision.
    DECLARE
      failed_work mission_generic_owner.work_items;
      released_source mission_generic_owner.unified_source_windows;
      retry_receipt mission_generic_owner.progress_receipts;
      second_work mission_generic_owner.work_items;
      second_source mission_generic_owner.unified_source_windows;
      second_receipt mission_generic_owner.progress_receipts;
      failed_id uuid;
      second_id uuid;
    BEGIN
      IF (result->'dispatch'->>'event_id') ~
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        failed_id:=(result->'dispatch'->>'event_id')::uuid;
        SELECT * INTO failed_work FROM mission_generic_owner.work_items w
          WHERE w.id=failed_id
            AND w.master_session_id=p_session AND w.kind='director';
        IF failed_work.id IS NOT NULL THEN
          SELECT * INTO released_source FROM mission_generic_owner.unified_source_windows sw
            WHERE sw.id=failed_work.authority_receipt_id
              AND sw.work_id=failed_work.id AND sw.master_session_id=p_session;
        END IF;
      END IF;
      IF failed_work.id IS NOT NULL AND released_source.id IS NOT NULL
        AND failed_work.state='failed' AND failed_work.finalized_at IS NOT NULL
        AND released_source.context->>'source_revision'=p_source_revision
        AND (released_source.superseded_reason='staff_failed_director_validation_retry' OR (released_source.id IN('d460a7be-a3a2-4ad8-9d3b-d2e929f2947e'::uuid,'f4f7185e-4aae-4edd-ac24-65f8dcfa36f5'::uuid) AND released_source.master_session_id='44078c5f-7001-4129-9506-e2f34e68c8ac'::uuid AND released_source.superseded_reason='staff_preprovider_request_retry'))
        AND released_source.consumed_message_id IS NULL
        AND result->'dispatch'->>'request_key'=failed_work.request_key::text
        AND mission_generic_owner.role_source_released_v4(released_source.id) THEN
        new_key:=mission_ai_service_owner.uuid5(failed_work.id,
          'mission-staff-released-director-retry/1:'||p_source_revision);
        SELECT * INTO retry_receipt FROM mission_generic_owner.progress_receipts pr
          WHERE pr.request_key=new_key;
        IF retry_receipt.request_key IS NOT NULL THEN
          IF retry_receipt.master_session_id<>p_session
            OR retry_receipt.actor_user_id<>p_user
            OR retry_receipt.result_sha256<>public.combat_v2_sha256(retry_receipt.result)
          THEN RAISE EXCEPTION 'MGS_TICK_RETRY_RECEIPT_CONFLICT' USING ERRCODE='40001'; END IF;
          IF (retry_receipt.result#>>'{dispatch,event_id}') ~
             '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
            second_id:=(retry_receipt.result#>>'{dispatch,event_id}')::uuid;
            SELECT * INTO second_work FROM mission_generic_owner.work_items w
              WHERE w.id=second_id AND w.master_session_id=p_session AND w.kind='director';
            IF second_work.id IS NOT NULL THEN
              SELECT * INTO second_source FROM mission_generic_owner.unified_source_windows sw
                WHERE sw.id=second_work.authority_receipt_id
                  AND sw.work_id=second_work.id AND sw.master_session_id=p_session;
            END IF;
          END IF;
          IF second_work.id IS NOT NULL AND second_source.id IS NOT NULL
            AND second_work.state='failed' AND second_work.finalized_at IS NOT NULL
            AND second_source.context->>'source_revision'=p_source_revision
            AND second_source.superseded_reason='staff_failed_director_validation_retry'
            AND second_source.consumed_message_id IS NULL
            AND retry_receipt.result#>>'{dispatch,request_key}'=second_work.request_key::text
            AND mission_generic_owner.role_source_released_v4(second_source.id) THEN
            failed_work:=second_work;
            released_source:=second_source;
            new_key:=mission_ai_service_owner.uuid5(second_work.id,
              'mission-staff-db-context-retry/2:'||p_source_revision);
            SELECT * INTO second_receipt FROM mission_generic_owner.progress_receipts pr
              WHERE pr.request_key=new_key;
            IF second_receipt.request_key IS NOT NULL THEN
              IF second_receipt.master_session_id<>p_session
                OR second_receipt.actor_user_id<>p_user
                OR second_receipt.result_sha256<>public.combat_v2_sha256(second_receipt.result)
              THEN RAISE EXCEPTION 'MGS_TICK_SECOND_RECEIPT_CONFLICT' USING ERRCODE='40001'; END IF;
              RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
                'state','replayed','source_revision',p_source_revision,
                'request_key',new_key,'progress',second_receipt.result);
            END IF;
          ELSE
            RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
              'state','replayed','source_revision',p_source_revision,
              'request_key',new_key,'progress',retry_receipt.result);
          END IF;
        END IF;
        IF EXISTS(SELECT 1 FROM mission_generic_owner.work_items newer
          WHERE newer.master_session_id=p_session AND newer.created_at>failed_work.created_at)
        THEN RAISE EXCEPTION 'MGS_TICK_RETRY_NEWER_WORK' USING ERRCODE='40001'; END IF;
      END IF;
    END;
    END IF;
    IF new_key IS NULL THEN
      RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
        'state','replayed','source_revision',p_source_revision,
        'request_key',tick.request_key,'progress',result);
    END IF;
  END IF;
  -- Una revisione nuova non bypassa work/provider incerti della precedente.
  pending:=public.mission_generic_dispatch_next_v1(p_session,p_user);
  IF jsonb_typeof(pending->'request')='object' THEN
    RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
      'state','existing_work','source_revision',p_source_revision,
      'request_key',null,'progress',jsonb_build_object(
        'schema_version','mission-generic-progress/1',
        'master_session_id',p_session,'state','work_pending','dispatch',null));
  END IF;
  IF EXISTS (SELECT 1 FROM mission_generic_owner.work_items w
    WHERE w.master_session_id=p_session AND w.state IN ('ready','claimed','authorized','provider_started'))
    OR EXISTS (SELECT 1 FROM mission_generic_owner.unified_source_windows sw
      WHERE sw.master_session_id=p_session AND sw.consumed_message_id IS NULL AND sw.superseded_at IS NULL)
    OR EXISTS (SELECT 1 FROM public.combat_v2_sessions cs
      WHERE cs.master_session_id=p_session AND cs.closed_at IS NULL)
  THEN RAISE EXCEPTION 'MGS_TICK_ACTIVE_OR_UNCERTAIN_WORK' USING ERRCODE='55000'; END IF;
  SELECT EXISTS (SELECT 1 FROM jsonb_array_elements(
    mission_generic_owner.run_plan_settings(p_session)->'terminal_steps') t
    WHERE t->>'step_key'=r.current_step_key) INTO terminal;
  IF terminal THEN RAISE EXCEPTION 'MGS_TICK_TERMINAL_STEP' USING ERRCODE='55000'; END IF;
  IF diag->>'flow_reason'<>'ready_to_evaluate'
  THEN RAISE EXCEPTION 'MGS_TICK_SOURCE_CHANGED' USING ERRCODE='40001'; END IF;
  new_key:=coalesce(new_key,gen_random_uuid());
  result:=mission_generic_owner.progress_step(p_session,p_user,new_key);
  INSERT INTO mission_generic_owner.progress_receipts
    (request_key,master_session_id,actor_user_id,result,result_sha256)
  VALUES(new_key,p_session,p_user,result,public.combat_v2_sha256(result));
  IF tick.request_key IS NULL THEN
    INSERT INTO mission_generic_owner.staff_progress_ticks_v1
      (master_session_id,source_revision,request_key,actor_user_id,staff_user_id,result_sha256)
    VALUES(p_session,p_source_revision,new_key,p_user,p_staff,public.combat_v2_sha256(result));
  END IF;
  RETURN jsonb_build_object('schema_version','mission-generic-staff-tick/1',
    'state','issued','source_revision',p_source_revision,
    'request_key',new_key,'progress',result);
END;
$function$

staff_ai_quota_private__reserve.sql.source:
CREATE OR REPLACE FUNCTION staff_ai_quota_private.reserve(p_producer text, p_source_id uuid, p_call_no integer, p_scope_id uuid, p_model text, p_upper_usd numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pol staff_ai_quota_private.runtime%rowtype;
  price staff_ai_quota_private.prices%rowtype;
  prior staff_ai_quota_private.calls%rowtype;
  used_calls bigint;used_usd numeric;reserved staff_ai_quota_private.calls%rowtype;
  asof timestamptz:=clock_timestamp();
begin
  if p_producer is null or p_source_id is null or p_call_no is null or p_scope_id is null
    or p_model is null or p_upper_usd is null or p_upper_usd<=0 or p_upper_usd>0.20
  then raise exception 'STAFF_QUOTA_ARGUMENT_INVALID' using errcode='22023';end if;
  select * into strict pol from staff_ai_quota_private.runtime where singleton for update;
  if pol.admissions_paused then raise exception 'STAFF_QUOTA_ADMISSIONS_PAUSED' using errcode='55000';end if;
  if not pol.enabled then raise exception 'STAFF_QUOTA_DISABLED' using errcode='P0001';end if;
  select * into strict price from staff_ai_quota_private.prices where model=p_model;
  select * into prior from staff_ai_quota_private.calls
    where producer=p_producer and source_id=p_source_id and call_no=p_call_no;
  if found then
    if prior.scope_id<>p_scope_id or prior.model<>p_model or prior.reserved_usd<>p_upper_usd then
      raise exception 'STAFF_QUOTA_SOURCE_CONFLICT' using errcode='23505';
    end if;
    return jsonb_build_object('call_id',prior.id,'granted_now',false,
      'may_send_http',false,'state',prior.state);
  end if;
  -- Una violazione del tetto per singola chiamata è già un incidente di spesa:
  -- non autorizzare nuove POST Staff nella finestra finché non esce o non viene
  -- risolta con un intervento esplicito e revisionato. I replay restano negati.
  if exists(select 1 from staff_ai_quota_private.calls c
    where c.state='over_cap' and c.created_at>=asof-make_interval(days=>pol.window_days)) then
    raise exception 'STAFF_QUOTA_OVER_CAP_HALT' using errcode='P0001';
  end if;
  select count(*),coalesce(sum(case when c.state in('settled','over_cap')
      then c.charged_usd else c.reserved_usd end),0)
    into used_calls,used_usd
  from staff_ai_quota_private.calls c
  where c.created_at>=asof-make_interval(days=>pol.window_days)
    and c.created_at<=asof and c.state<>'no_http';
  if (NOT (p_producer='mission_generic_ai' AND p_call_no IN(1,2) AND mission_generic_owner.manual_staff_count_limit_v1(p_scope_id)='none' AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts mr JOIN mission_generic_owner.work_items mw ON mw.id=mr.authority_receipt_id AND mw.dispatch_receipt_id=mr.id AND mw.master_session_id=mr.master_session_id WHERE mr.id=p_source_id AND mr.master_session_id=p_scope_id AND mr.event_kind='mission_generic_event' AND mr.renderer_version='mission-generic-runtime/1' AND mw.payload_sha256=public.combat_v2_sha256(mw.payload))) AND used_calls+1>pol.max_calls) or used_usd+p_upper_usd>pol.max_total_usd then
    raise exception 'STAFF_QUOTA_EXHAUSTED' using errcode='P0001';
  end if;
  insert into staff_ai_quota_private.calls
    (producer,source_id,call_no,scope_id,model,pricing_version,input_usd_million,
      output_usd_million,state,reserved_usd,created_at)
    values(p_producer,p_source_id,p_call_no,p_scope_id,p_model,price.pricing_version,
      price.input_usd_million,price.output_usd_million,'reserved',p_upper_usd,asof)
    returning * into reserved;
  return jsonb_build_object('call_id',reserved.id,'granted_now',true,
    'may_send_http',false,'state','reserved',
    'remaining_calls',CASE WHEN p_producer='mission_generic_ai' AND p_call_no IN(1,2) AND mission_generic_owner.manual_staff_count_limit_v1(p_scope_id)='none' AND EXISTS(SELECT 1 FROM mission_narrative_internal.dispatch_receipts mr JOIN mission_generic_owner.work_items mw ON mw.id=mr.authority_receipt_id AND mw.dispatch_receipt_id=mr.id AND mw.master_session_id=mr.master_session_id WHERE mr.id=p_source_id AND mr.master_session_id=p_scope_id AND mr.event_kind='mission_generic_event' AND mr.renderer_version='mission-generic-runtime/1' AND mw.payload_sha256=public.combat_v2_sha256(mw.payload)) THEN NULL ELSE pol.max_calls-used_calls-1 END,'remaining_usd',pol.max_total_usd-used_usd-p_upper_usd);
end $function$

manual_count_policy_ddl.sql.source:
ALTER TABLE mission_generic_owner.dispatch_admissions ADD COLUMN manual_count_limit text NOT NULL DEFAULT 'bounded' CHECK(manual_count_limit IN('bounded','none'));
ALTER TABLE mission_generic_owner.dispatch_admissions DROP CONSTRAINT dispatch_admissions_check;
ALTER TABLE mission_generic_owner.dispatch_admissions ADD CONSTRAINT dispatch_admissions_check CHECK(scene_budget_mode='staff_scene_uncapped' OR manual_count_limit='none' OR calls_authorized<=call_limit);
