CREATE OR REPLACE FUNCTION mission_generic_owner.manual_staff_count_limit_v1(p_session uuid)
RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO ''
AS $function$
DECLARE q jsonb;policy jsonb;root mission_factory_owner.editor_release_readiness;
BEGIN
 SELECT * INTO root FROM mission_factory_owner.editor_release_readiness WHERE singleton;
 IF root.state IS DISTINCT FROM 'enabled' OR root.revision_sha256 IS DISTINCT FROM root.observed_revision_sha256
  OR root.revision_sha256 IS DISTINCT FROM encode(extensions.digest(convert_to(root.canonical_preimage,'UTF8'),'sha256'),'hex') THEN RETURN 'bounded';END IF;
 policy:=root.canonical_preimage::jsonb#>'{config,c1266_manual_staff_count_policy}';
 IF policy IS DISTINCT FROM jsonb_build_object('schema_version','c1266-manual-staff-count-policy/1','manual_count_limit','none','location_id','0b85f354-9cdb-47e1-baf9-3d266bb7e06b','admission_authority','c1266-manual-staff-admission/1','money_policy','existing','token_policy','existing') THEN RETURN 'bounded';END IF;
 q:=mission_generic_owner.manual_staff_scope_v1(p_session);
 IF q IS NULL OR q->>'schema_version' IS DISTINCT FROM 'c1266-manual-staff-admission/1'
  OR q->>'location_id' IS DISTINCT FROM policy->>'location_id'
  OR NOT EXISTS(SELECT 1 FROM public.master_v2_sessions ms JOIN public.locations l ON l.id=ms.location_id AND l.is_test AND l.is_active
    JOIN public.profiles pr ON pr.id=(q->>'actor_user_id')::uuid AND pr.role IN('admin','master')
    WHERE ms.id=p_session AND ms.owner_kind='ai_service' AND ms.master_user IS NULL AND ms.closed_at IS NULL AND ms.suspended_at IS NULL)
 THEN RETURN 'bounded';END IF;
 RETURN 'none';
END;
$function$;
ALTER FUNCTION mission_generic_owner.manual_staff_count_limit_v1(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION mission_generic_owner.manual_staff_count_limit_v1(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION mission_generic_owner.manual_staff_count_limit_v1(uuid) TO service_role;

