BEGIN
 SELECT pg_get_constraintdef(c.oid),c.convalidated INTO STRICT d,v FROM pg_constraint c WHERE c.conrelid='public.mission_run_audit'::regclass AND c.conname='mission_run_audit_event_code_check';
 IF d IS DISTINCT FROM 'CHECK ((event_code ~ ''^[A-Z][A-Z0-9_]{1,79}$''::text))' OR v IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'MANUAL_AUDIT_CONSTRAINT_BASELINE_DRIFT' USING ERRCODE='40001';END IF;
 SELECT count(*),public.combat_v2_sha256(coalesce(jsonb_agg(jsonb_build_object('id',a.id,'sha256',public.combat_v2_sha256(to_jsonb(a))) ORDER BY a.id),'[]'::jsonb)) INTO n,h FROM public.mission_run_audit a;
